                'kesimpulan' => '<p><strong><u>Mikrobiologi </u></strong></p><p>- Blok 4.1</p><p>Tambahan materi perkuliahan ketiga : emerging dan re-emerging pulmonary disease &amp; mekanisme terjadinya re-emerging</p><p><br></p><p>- Blok 4.2 </p><p>Untuk kuliah mikroba penginfeksi sal. Cerna dan hepatobilier untuk jenis mikroba disesuaikan dgn aspek klinis</p><p><br></p><p>- Blok 4.3</p><p><br></p><p><strong><u>Parasitologi</u></strong></p>',
