                'kesimpulan' => '<p><strong>Blok 6.1</strong> : -</p><p><strong>Blok 6.2</strong> :</p><ul><li>penambahan materi pembelajaran perkosaan dan pencabulan pada anak dan remaja pada sub pokok bahasan masalah medikolegal yang terjadi pada anak dan remaja</li></ul>',
