            18 => 
            array (
                'id' => 22,
                'presensi_id' => 29,
                'maker_id' => 4,
                'slug' => 'ggPv2Uzlfox588SogiNU',
            'kesimpulan' => '<p>Feedback perkuliahan tahun lalu:</p><ul><li>Usulan: pedoman nasional --&gt; dimasukkan ke materi pembelajaran. Konten materi sudah ada semua di setiap sistem</li><li>Mahasiswa --&gt; kurang ide dan knowledge</li><li>Pemaparan materi promotif dan preventif masih kurang --&gt; solusi: revisi program dengan membuat poster (promotif dan preventif) --&gt; diberikan sebelum semester 7</li><li>Metodenya rencana akan dibuat berjenjang, untuk urutannya bisa dikonsulkan ke dr. Vivi</li></ul><p><br></p><p><u>Semester 4</u></p><p><u>Blok 4.1:</u></p><ul><li>Membuat poster</li><li>Penyuluhan</li><li>Mengevaluasi program pemerintah (promotif, preventif)</li><li>Belajar membuat diagnosis dari data yg diberikan</li></ul><p><br></p><ol><li>untuk mempelajari penyakit kardiorespi</li><li>untuk menentukan media promkes --&gt; membuat tools</li><li>untuk mengaplikasikan media promkes</li></ol><p><br></p><ul><li>2x50 menit: sasbel sudah diberikan (kasus + sasbel)</li><li>2x50 menit: diskusi panel</li></ul><p><br></p><p>GBPP blok 4.1; 4.2; 4.3 --&gt; perubahan redaksi saja</p><p>GBPP blok 6.2: berubah</p><p><br></p><p>Materi kuliah pakar 6.3 tetap sama, narasumber di follow up lagi</p><p>Kuliah 6.2 selama 3x50 menit mengenai pelayanan primer pada kesehatan remaja dan jiwa akan dibagi dibagi 3 yang masing2 berdurasi 2x50 menit:</p><ul><li>Kuliah</li><li>Praktikum</li><li>Diskusi panel</li></ul><p>Dan kemungkinan akan diperkenalkan atau dimulai dari blok 5.3</p>',
                'tindaklanjut' => '<p>materi perkuliahan berjenjang kan dimulai dari blok 5.3</p>',
                'notulis_id' => 108,
                'pimpinan_id' => 5,
                'created_at' => '2023-02-22 03:11:44',
                'updated_at' => '2023-02-22 05:41:44',
            ),
            19 => 
            array (
