            'kesimpulan' => '<p><strong>Departemen Farmakologi</strong></p><p><u>Blok 3.1</u></p><p>pertukaran materi dari blok 3.2 tentang prinsip peresepan obat:</p><ul><li>2x50\' : prinsip pemberian obat secara rasional dan macam Sediaan Obat</li><li>2x50\' : tata cara peresepan obat</li></ul><p><u>Blok 3.2</u></p><p>pertukaran materi dari blok 3.1 tentang antimikroba:</p><ul><li>2x50\' : antibiotika</li><li>1x50\' : antiparasit</li><li>1x50\' : antivirus</li></ul><p><u>Blok 3.3</u></p><ul><li>Follow up untuk penjabaran poin-poin ke departemen farmakologi tentang materi perkuliahan farmakologi muskuloskeletal</li></ul><p><u>Blok 5.1</u></p><ul><li>penambahan materi tentang penatalaksanaan pada pasien diabetes mellitus</li></ul><p><br></p><p><strong>Departemen Neurologi</strong></p><p><u>Blok 1.3</u></p><ul><li>masih relevan</li></ul><p><u>Blok 3.3</u></p><ul><li>kuliah : masih relevan</li><li>PBL : 1 (migrain) , 2 (stroke hemoragik / iskemik), Dan 3 (status epileptikus. Tambahkan sasaran belajar: tatakelola)</li></ul><p><u>Blok 7.1</u></p><ul><li>masih relevan</li></ul><p><br></p>',
