                'slug' => 'vwOGkxd3vY5awCWq4wBx',
            'kesimpulan' => '<p>Kasus CR 1 Bedah Saraf (EDH)</p><p>Kasus CR 2 Obsgyn (Solusio Plasenta)</p><p>Kasus CR 3 Anak (Kejang Neonatus)</p><p>Kasus CR 4 Mata (Trauma Kimia)</p><p>Kasus CR 5 Kulit (Eritroderma e.c Perluasan Psoriasis)</p><p>Kasus CR 6 Muskuloskeletal (Fraktur Humerus)</p><p>Kasus CR 7 Cardiovaskular (Gagal Jantung Akut)</p><p>Kasus CR 8 Bedah (Apendisitis Akut)</p><p>Kasus CR 9 IPD (Ketoasidosis Diabetikum)</p><p>Kasus CR 10 IPD (DSS + Efusi Pleura)</p>',
