                'slug' => 'Etf407vLRAyUxSapfoKI',
            'kesimpulan' => '<p>PJ Melaporkan tiap semester :</p><ol><li>Jumlah mahasiswa dlm periode</li><li>tingkat kellulusan</li><li>nilai</li><li>pencapaian kompetensi</li><li>laporan 10 penyakit terbanyak</li><li>Rekapan time activity (bimbingan perseptor) selama 1 stase&nbsp;</li><li class="ql-indent-1">Bed Site Teaching - sesuaikan jadwal poli</li><li class="ql-indent-1">kegiatan lainnya sesuai log book&nbsp;</li></ol><p>Pelaporan sesuai genap lalu dan ganjil sekarang</p><p><br></p><p><br></p><p>Pengajuan honor dan masuknya nilai ke FK belum sesuai waktunya, diajukan 1mgg sejak stase dimulai</p><p><br></p><p>Stase neuro di RSUD45</p><p>Kebutuhan sarpras lt2 : CS</p><p> Berkas nilai di RSUD 45</p><p>Kebutuhan buku di RSUD 45 dipending karena blm ada tempat</p><p><br></p><p>bembi UKMPPD pertengahan Desember</p><p><br></p><p>Pembuatan Buku Log Dosen&nbsp;</p><p><br></p>',
            'tindaklanjut' => '<p>PJ Melaporkan tiap semester :</p><ol><li>Jumlah mahasiswa dlm periode</li><li>tingkat kellulusan</li><li>nilai</li><li>pencapaian kompetensi</li><li>laporan 10 penyakit terbanyak</li><li>Rekapan time activity (bimbingan perseptor) selama 1 stase&nbsp;</li><li class="ql-indent-1">Bed Site Teaching - sesuaikan jadwal poli</li><li class="ql-indent-1">kegiatan lainnya sesuai log book&nbsp;</li></ol><p>Pelaporan sesuai genap lalu dan ganjil sekarang</p><p><br></p><p><br></p><p>Pengajuan honor dan masuknya nilai ke FK belum sesuai waktunya, diajukan 1mgg sejak stase dimulai</p><p><br></p><p>Stase neuro di RSUD45</p><p>Kebutuhan sarpras lt2 : CS</p><p> Berkas nilai di RSUD 45</p><p>Kebutuhan buku di RSUD 45 dipending karena blm ada tempat</p><p><br></p><p>bembi UKMPPD pertengahan Desember</p><p><br></p><p>Pembuatan Buku Log Dosen&nbsp;</p><p><br></p>',
