                'slug' => '1XPVOqabERgEwCS8ovT9',
            'kesimpulan' => '<p><strong>-----------------SKENARIO BLOK 3.3-------------------------</strong></p><p><u>Skenario 1 :</u>  Nyeri kepala</p><p><em>Tg : Migrain</em></p><p>mini note: </p><ul><li>Nyeri kepala asal dari mana -  patofisiologi nyeri kepala - klasifikasi nyeri kepala ( primer &amp; sekunder )</li><li>patofisiologi yg dimaksud untuk nyeri kepala sekunder adalah mengapa pada stroke/ht dapat meyebabkan nyeri kepala ?</li></ul><p><br></p><p><u>Skenario 2 : </u>Bibir Mencong</p><p>Tg : Stroke iskemik</p><p>mininote :</p><ul><li>konsulkan ke Sp. S untuk tatalaksana pemberian manitol terkait kenaikan TTIK pada stroke iskemik serta tatalaksana awalnya</li></ul><p><br></p><p><u>Skenario 3 : Kejang</u></p><p>Tg :Status Epileptikus</p><p>Mininote : </p><ul><li>Kompliksi munculkan dimininote tidak perlu diskenario</li></ul><p><br></p><p><u>Skenario 4 : Sulit Menelan</u></p><p>Tg: Gang. menelan (abses peritonsilar) - ganti jadi tonsilitis</p><p>Mininote : </p><p><br></p><p><br></p><p><u>Skenario 5 : Kehilangan pengelihatan</u></p><p><u>Tg: methanol toxic neuropaty</u></p><p>Mininote:</p><p>Skenario dan mininotes dikonsulkan kembali ke pengampu</p><p><br></p><p><strong>----------------------SKENARIO BLOK 1.3------------------------------------</strong></p><p>Skenario 1 :</p><p>tg:</p><p>Mininote: tidak ada tambahan</p><p><br></p><p>Skenario 2 : Kebas Pada Kaki Kiri</p><p>tg: pemeriksaan neurologi</p><p>Mininote:</p><p><br></p><p>Skenario 3 : Moon Face </p><p>tg: Adenohipofisis</p><p>Mininote: </p><p><br></p><p>Skenario 4 : Mata Merah</p><p>tg: Mata merah</p><p>Mininote :</p><p><br></p><p>Skenario 5 : Menier Disease</p><p>tg: Vertigo</p><p>Mininote:</p>',
