            85 => 
            array (
                'id' => 93,
                'presensi_id' => 108,
                'maker_id' => 4,
                'slug' => 'ICZTVKhyHQ1rNDYC1C51',
            'kesimpulan' => '<p><strong>Trigger PBL</strong></p><p><u>Blok 2.1</u></p><ol><li>datang ke poliklinik jantung dengan dada berdebar karena mau ujian  lalu di EKG didapatkan hasil gambaran EKG normal (struktur jantung dan elektrofisiologi jantung)</li><li>kaki bengkak setelah long marathon saat pemeriksaan tidak ada lecet / cedera (sirkulasi darah)</li><li>praktikum kesanggupan kardiovaskular : naik turun bangku - diukur sebelum dan sesudah (siklus jantung dan pompa jantung)</li><li>pemeriksaan spirometri dengan pasien normal (struktur dan fungsi sistem respirasi)</li><li>sesak napas saat didalam mobil: keracunan CO (fungsi dan pengaturan pernapasan, mekanisme pengendalian pernapasan normal dan faktor yang mempengaruhi)</li></ol><p><u>Blok 2.2</u></p><ol><li>diare saat stress revisi KTI tidak kunjung selesai konstipasi saat mau ujian (struktur sistem pencernaan)</li><li>mencium bau makanan jadi keroncongan lalu makan sistem pencernaan (fungsi sekresi traktus gastrointestinal)</li><li>diet namun tidak kunjung kurus (absorpsi karbohidrat, lemak, protein)</li><li>MCU pasien konsumsi alkohol, hasil laboratorium hepar, kolesterol (sistem hepatobilier)</li><li>BAB dempul (acholia/hipokolia), ikterik (metabolisme bilirubin)</li></ol><p><u>Blok 2.3</u></p><ol><li>sering BAK setelah minum kopi (proses pembentukan urin)</li><li>alkalosis metabolik - muntah (mekanisme keseimbangan asam basa)</li><li> tidak punya anak, faktor risiko merokok, alkoholik. hasil sperma terdapat kelainan jumlah dan morfologi (proses pembentukan sperma)</li><li>menopause (siklus menstruasi)</li><li>sindrom turner (embriologi genitalia, proses differensiasi organ genitalia)</li></ol><p><br></p><p><strong>GIZI </strong></p><ul><li>materi masih relevan </li><li>kuliah pakar 2.2: dietary fiber &amp; it\'s role in metabolic health </li><li>usulan: terapi gizi pada ginjal kronik (ditambahkan ke sasaran PBL 4 Blojk 4.3)  </li></ul><p><br></p><p><strong>ANATOMI</strong></p><p><u>Blok 2.1</u></p><ul><li>ditambahkan materi terminologi posisi jantung di materi kuliah struktur makroskopis jantung</li><li>aliran limfatik hanya diberikan pada perkuliahan (tidak diberikan pada saat praktikum)</li><li>materi sistem respirasi dibagi menjadi 2 perkuliahan dan praktikum:</li></ul><ol><li>saluran napas atas: laring, faring, pleura, trakea (kuliah 2x50\', praktikum 2x50\')</li><li>saluran napas bawah: segmen atas bronkus dan bronkopulmonary, paru, vaskularisasi sistem respirasi, aliran limfatik sistem respirasi (kuliah 2x50\', praktikum 2x50\')</li></ol><p><u>Blok 2.2</u></p><ul><li>materi bagian dalam abdomen dipisah untuk perkuliahannya dengan dinding abdomen (tambah jam 2x50\')</li></ul><p><u>Blok 2.3 </u></p><ul><li>materi organ dan traktus urinarius - ureter ditambahkan materi terminologi dan radiologi</li><li>materi organ genitalia wanita ditambahkan materi sistem limfatik genitalia wanita </li><li>materi embriologi sistem genitourinaria : kelainan yang dapat muncul pada perkembangan sistem genitourinaria di hapus </li></ul><p><br></p><p><strong>HISTOLOGI</strong></p><p><u>Blok 2.1</u></p><ul><li>struktur mikroskopis jantung dan pembuluh darah </li></ul><ol><li>jantung (lapirsan jantung dan strukturnya, struktur otot jantung)</li><li>pembuluh darah (struktur penyusun, perbedaan vena dan arteri, karakteristik pembuluh darah besar sedang dan kecil serta hubungannya dengan fungsi dalam sirkulasi</li></ol><ul><li>struktur mikroskopis pembuluh limfatik</li></ul><ol><li>struktur pembuluh limfatik </li><li>struktur lien </li></ol><ul><li>histologi hidung: sinus, tonsil, faring, laring, trakea (hidung [sistem respiratorik], sinus paranasal, tonsil palatins dan pharingeal, faring, laring trakea)</li><li>histologi bronkhus, paru, dan Pleura: bronkhus, bronkhiolus, bronkhiolus terminalis, bronkhiolus respiratorius, ductus dan saccus alveolaris, alveoli, septum interalveolaris, pembuluh limfe dan persarafan paru, Pleura</li></ul><p><u>Blok 2.2</u></p><ul><li>struktur mikroskopis saluran pencernaan: </li></ul><ol><li>cavum oris (bibir, gigi, lidah, tonsila lingualis)</li><li>esofagus</li><li>lambung dan kelenjar lambung </li><li>usus halus</li><li>appendix vermiformis</li><li>usus besar</li><li>anus </li></ol><ul><li>struktur mikroskopis sistem hepatobilier dan kelenjar pencernaan: kelenjar salivarius, pankreas (eksokrin), hepar, vesika felea dan salurannya</li></ul><p>Blok 2.3</p><ul><li>struktur mikroskopis traktus urinarius </li></ul><ol><li>ginjal (diagram nefron, bagian-bagian nefron, duktus koligens dan duktus papilaris bellini, korteks dan medulla ginjal, aparatus juxta glomerular, tubulus  kontortus I dan II, ansa henle, kaliks mayor/minor dan pervis renis)</li><li>traktus urinarius (ureter, vesika urinaria, uretra laki-laki dan perempuan)</li></ol><ul><li>traktus genitalia laki-laki</li></ul><ol><li>testis (tunika albuginea, septa testis dan lobulus testis, sel leydig dan fungsi, tubulus seminiferus, sel sertoli dan fungsi, duktus intratestikular [tubulus rectus, rete testis, duktus eferen])</li><li> duktus epididimis </li><li>duktus deferen</li></ol><ul><li>penis dan kelenjar genital </li></ul><ol><li>penis (tunika albuginea, septum pektiniformis, korpus spongiosum, korpus kavernosum, kaitan struktus mikroskopis penid dengan mekanisme ereksi penis)</li><li>kelenjar genital (kelenjar vesikulosa/ vesikulosa seminalis, kelenjar prostat, kelenjar bulbouretra)</li></ol><ul><li>organ genitalisa perempuan </li></ul><ol><li>ovarium(struktur umum, perkembangan awal folikel, folikel ovarium)</li><li>tuba uterina</li><li>uterus (struktur umum, fase proliferasi, fase sekresi, fase menstruasi)</li><li>serviks </li><li>vagina </li><li>genitalia eksterna (klitoris, kelenjar bartholini, labia minora, labia mayora)</li><li>plasenta (plasenta fetus, plasenta maternal)</li><li>kelenjar mammae (non laktasi, laktasi)</li></ol><p><br></p><p><strong>FISIOLOGI </strong></p><ul><li>masih relevan</li></ul><p><br></p><p><strong>BIOKIMIA </strong></p><p><u>Blok 2.1</u></p><ul><li>materi metabolisme porfiria:</li></ul><ol><li>metabolisme hemoglobin (pembentukan heme dan globin, pemecahan hemoglobin)</li><li>penyakit gangguan metabolisme heme </li></ol><p><u>Blok 2.2</u></p><ul><li>metabolisme makronutrien dan mikronutrien di pecah menjadi 2 kuliah:</li></ul><ol><li>metabolisme karbohidrat dan metabolisme lemak (2x50\')</li><li>metabolisme protein, asam nukleat, vitamin dan mineral (2x50\')</li></ol><ul><li>absropsi zat-zat gizi makro dan nukleoprotein:</li></ul><ol><li>abropsi hasil pencernaan karbihidrat, lemak dan protein makanan</li><li>prinsip dasar absorpsi astrointertinal </li><li>putrefraksi dan fermentasi</li><li>manfaat bakteri usus</li><li>dekarboksilasi asam amino oleh bakteri usus</li></ol><p><u>Blok 2,3</u></p><ul><li>masih relevan</li></ul><p><br></p><p><strong>BIOLOGI</strong></p><p><u>Blok 2.3</u></p><ul><li>masih relevan</li></ul>',
            'tindaklanjut' => '<p><strong>GIZI</strong></p><ul><li>konsul  ke dr. Ali, Sp.GK mengenai mininotes terapi gizi pada ginjal kronik (PBL 4 Blok 4.3)</li></ul><p><br></p><p><strong>ANATOMI</strong> </p><ul><li><u>Blok 2.1</u><strong> - </strong>sub pokok bahasan sistem respisasi tambah jam (kuliah 2x50\', praktikum 2x50\')</li><li><u>Blok 2.2</u><strong> - </strong>sub pokok bahasan bagian dalam abdomen dipisah (tambah jam 2x50\')</li></ul><p><br></p><p><strong>BIOKIMIA</strong> </p><ul><li><u>Blok 2.2</u><strong> - </strong>sub pokok bahasan metabolisme makronutrien dan mikronutrien tambah jam 2x50\'</li></ul>',
