                'maker_id' => 4,
                'slug' => 'hpgfted3kP7trIhqBPzr',
            'kesimpulan' => '<p class="ql-align-center"><strong>Departemen Forensik dan Medikolegal</strong></p><p><u>Blok 6.1</u></p><ul><li>materi kekerasan pada ibu dan bayi (terbatas di lingkup forensik: kekerasan pada ibu dan bayi)</li><li>usulan tambahan jam materi hukum kesehatan reproduksi 2x50\'</li></ul><p><u>Blok 6.2</u></p><ul><li>masih relevan</li></ul><p class="ql-align-center"><br></p><p class="ql-align-center"><strong>Departemen Ilmu Kesehatan Jiwa</strong></p><p><u>Blok 6.1</u></p><ul><li>masih relevan</li></ul><p><u>Blok 6.2</u></p><p><strong>Kuliah</strong></p><ul><li>terapi psikiatrik &gt; materi diubah menjadi penggunaan psikofarmakoterapi pada praktik klinis (G62.14..2)</li><li>usulan penambahan jam kuliah 2x50\' materi simtomatologi, sistem pertahanan jiwa dan penilaian status mental (diberikan sebelum PBL)</li><li>kuliah pakar: masih sama dengan tahun sebelumnya (dr. Vera)</li></ul><p><strong>PBL</strong></p><ul><li>Trigger kasus:</li></ul><ol><li>PBL 4: skizofrenia</li><li>PBL 5: autisme / retardasi mental</li></ol><ul><li>sasaran belajar PBL 4: ditambahkan klasifikasi gangguan jiwa (spesifik dimasukan kedalam mininotes)</li><li>sasaran belajar PBL 5: diganti menjadi gangguan emosional dan perilaku dengan onset khusus pada masa anak dan remaja</li></ul><p><br></p><p><u>Blok 6.3</u></p><p><strong>Kuliah</strong></p><ul><li>usulan materi gangguan neurotik, gangguan berhubungan dengan stres, gangguan somatoform, dan gangguan tidur 2x50\'</li><li>usulan materi kegawatdaruratan psikiatri (2x50\')</li></ul><p><strong>PBL </strong></p><ul><li>Trigger kasus:</li></ul><ol><li>PBL 1: depresi - gangguan jiwa non psikotik diberikan sebelum kuliah (pindahan dari blok 6.2 SK-5)</li><li>PBL 2: gangguan cemas - ganggan neurotik ditambahkan sasaran belajar gangguan tidur (awal: PBL 1)</li><li>PBL 3: Demensia dengan gangguan perilaku</li></ol><p><br></p>',
            'tindaklanjut' => '<p>Departemen Forensik dan Medikolegal</p><ul><li>blok 6.1 - penambahan jam kuliah 2x50\' dengan materi hukum kesehatan reproduksi</li></ul><p><br></p><p>Departemen Ilmu Kesehatan Jiwa</p><ul><li>blok 6.2 - penambahan jam kuliah 2x50\' materi simtomatologi, sistem pertahanan jiwa dan penilaian status mental (catatan: kuliah diberikan sebelum PBL)</li><li>blok 6.3 penambahan jam:</li></ul><ol><li>materi gangguan neurotik, gangguan berhubungan dengan stres, gangguan somatoform dan gangguan tidur (2x50\')</li><li>materi kegawatdaruratan psikiatri (2x50\')</li></ol>',
