                'slug' => 'IirEggspJQNYcH2XsiDJ',
                'kesimpulan' => '<p><strong>Departemen Ilmu Kesehatan Kulit dan Kelamin</strong></p><p><u>Kuliah</u></p><ul><li>Kuliah 1: penentuan status dermatologis, mekanisme sistem imun pada kulit dan mukosa hubungannya dengan agen penyebab kelainan tetap ada</li><li>Kuliah 2: kondiloma akuminata, tambahan viral exanthem, herpes gestasional</li><li>Kuliah 3: sesuai</li><li>Kuliah 4: sesuai</li><li>Kuliah 5: sesuai</li><li>Kuliah 6: ditambahkan dermatitis perioral, ditambhakan PUPPP</li><li>Kuliah 7: sesuai</li><li>Kuliah 8: pemfigoid bulosa,</li><li>Kuliah 9: judul diganti kelainan kelenjar sebasea , kelenjar ekrin dan kelainan kosmetik, tambah poin miliaria</li><li>Kuliah 10: sesuai</li><li>Kuliah 11: sesuai</li><li>Kulaih 12: ditambahkan pemfigus vulgaris , psoriasis pustulosa generalisata.</li><li>Kuliah 13: sesuai</li></ul><p><u>Trigger PBL</u></p><p>Skenario 1: Varicella</p><p>Skenario 2: MH reaksi ENL</p><p>Skenario 3: Dermatitis perioral</p><p>Skenario 4: Servisitis GO/ uretritis GO</p><p><br></p><p><strong>Departemen farmakologi</strong></p><ul><li>Blok 4.1 kuliah dan praktikum sesuai</li><li>Blok 4.2 kuliah dan praktikum sesuai</li><li>Blok 4.3 kuliah dan praktikum sesuai</li><li>Blok 6.1 sesuai</li><li>Blok 6.2 sesuai</li><li>Blok 6.3 kuliah dan praktikum sesuai</li></ul>',
