                'kesimpulan' => '<p class=',
            'tindaklanjut' => '<p>Konsul terkait waktu tambahan jamnya</p><ul><li>Reproduksi Perempuan 1x50"</li><li>Reproduksi Laki-laki 1x50"</li><li>Payudara 1x50"</li></ul><p><span style="background-color: rgb(255, 255, 102);">sudah dikonsulkkan : tidak dapat diimplementasikan karena keterbatasan waktu</span></p><p><span style="background-color: rgb(255, 255, 102);">HASIL:</span></p><ul><li>Reproduksi Perempuan 1x50"</li><li>Reproduksi Laki-laki &amp; Payudara 1x50"</li></ul><p><br></p>',
                'notulis_id' => 109,
