            94 => 
            array (
                'id' => 102,
                'presensi_id' => 118,
                'maker_id' => 4,
                'slug' => '4QsPHKPAhejwcLJdhGoE',
            'kesimpulan' => '<p class="ql-align-center"><strong>REVIEW SKENARIO BLOK 2.1</strong></p><p class="ql-align-justify"><strong>Pbl Ke 1 - Dada berdebar</strong></p><p class="ql-align-justify"><em>Trigger</em> : datang ke polikinik jantung dengan dada berdebar-debar mau ujian dan didapatkan hasil gambaran ekg normal.</p><p class="ql-align-justify"><u>Note:</u></p><ul><li class="ql-align-justify">Skenario dan sasbel tidak ada tambahan</li><li class="ql-align-justify">Gambaran EKG dideskripsikan agar dapat menghubungkan dengan system konduksinya.</li><li class="ql-align-justify">Mininotes diupdate Kembali untuk terbaru-nya (koordinasikan dengan IKD)</li></ul><p class="ql-align-justify"><strong>PBL ke 2 - Bengkak setelah Marathon</strong></p><p class="ql-align-justify"><em>Trigger :</em> kaki bengkak setelah long marathon saat pemeriksaan tidak ada lecet.\\</p><p class="ql-align-justify"><u>Note :</u></p><ul><li class="ql-align-justify">Skenario dan sasbel tidak ada tambahan</li><li class="ql-align-justify">Mininotes diupdate kembali untuk terbaru-nya (koordinasikan dengan IKD)</li></ul><p class="ql-align-justify"><strong>PBL ke 3 – Kesanggupan Kardiovaskular</strong></p><p class="ql-align-justify"><em>Trigger</em> : Praktikum kesanggupan kardiovaskular naik turun bangku – diukur sebelum dan sesudah</p><p class="ql-align-justify">Note :</p><ul><li class="ql-align-justify">Skenario dan sasbel tidak ada tambahan</li><li class="ql-align-justify">Tekanan darah sistolik dan diastolic dijabarkan. Agar mahasiswa dapat mengubungkan dengan siklus jantung</li><li class="ql-align-justify">Mininotes diupdate Kembali untuk terbaru-nya (koordinasikan dengan IKD)</li></ul><p class="ql-align-justify"><strong>PBL ke 4 – Pemeriksaan Spirometri</strong></p><p class="ql-align-justify"><em>Trigger</em> : Pemeriksaan Spirometri </p><p class="ql-align-justify">Note :</p><ul><li class="ql-align-justify">Skenario dan sasbel tidak ada tambahan</li><li class="ql-align-justify">Mininotes diupdate kembali untuk terbaru-nya (koordinasikan dengan IKD)</li></ul><p class="ql-align-justify"><strong>PBL ke 5 – Keracunan Karbon Monoksida</strong></p><p class="ql-align-justify"><em>Trigger : Sesak Nafas saat didalam mobil (keracunan CO)</em></p><p class="ql-align-justify">Note :</p><ul><li class="ql-align-justify">Skenario dan sasbel tidak ada tambahan</li><li class="ql-align-justify">Mininotes diupdate kembali untuk terbaru-nya (koordinasikan dengan IKD)</li></ul><p class="ql-align-justify">&nbsp;</p>',
