            99 => 
            array (
                'id' => 107,
                'presensi_id' => 123,
                'maker_id' => 6,
                'slug' => 'zMQmKxcxfHXTh9AqpKit',
            'kesimpulan' => '<p><strong>Persamaan Persepsi DPK Stase Kompre</strong></p><p><br></p><p><strong>Evaluasi :&nbsp;</strong></p><ul><li>beberapa mahasiswa memiliki isi portofolio yang mirip/sama dengan temannya</li><li>Mahasiswa harus ditanyakan atau diingatkan atau diberikan trigger dulu</li><li>beberapa mahasiswa tidak sesuai dengan P1-P4 dalam penyusunan laporan</li></ul><p><br></p><p><strong>Materi dr. Vivi Meidianawaty M.Med.Ed</strong></p><p>&gt; Diharapkan dari refleksi diri ini didapatkan pelajaran untuk menyusun langkah yang lebih baik di masa depan..</p><p>&gt; Jika arahan dan bimbingan sesuai proses seharusnya tidak ada refleksi diri yang sama</p><p>&gt; Proses refleksi perlu dibantu masukan orang lain yang dianggap mampu memberikan umpan balik yang konstruktif</p><p><br></p><p>&gt; Proses Refleksi Diri :</p><ul><li>Apa yang terjadi... Kenapa terlambat mengumpulkan? Kenapa P1 dan P2nya tidak lengkap?</li><li>Bagaimana hal itu terjadi....Kendalanya dimana sehingga terlambat? Kendalanya dimana sehingga P1 dan P2 tidak lengkap ?</li><li>Pelajaran apa yang kamu ambil dari pengalaman ini.... dgn tujuan dpt mengcapture baik - atau +nya</li><li>Apa yang akan dilakukan untuk kedepannya.. nanti bagaimana kalau ada problem yang sama? apa yang dilakukan ?</li></ul><p>&gt;Tahapan Refleksi Diri :</p><ul><li>Tentukan 1 pengalaman berhaga</li><li>Analisis pengalaman dgn 4 pertanyaan diatas</li><li>Usahakan bukti eksternal (umpan balik dari berbagai pihak/log book)</li><li>Pembimbing sebagai teman sharing hasil refleksi&nbsp;</li></ul><p><br></p><p>&gt; Refleksi yang baik mencakup :</p><ul><li>Deskripsi pengalaman yang relevan dengan pemicu</li><li>Komponen refleksi (pelajaran yang didapat)</li><li>Bukti eksternal</li><li>Merujuk pada pengalaman sebelumnya&nbsp;</li><li>Action plan&nbsp;</li></ul><p><br></p><p><strong>Materi dr. Tissa Octavira, M.Med.Ed</strong></p><p>Memfasilitasi mahasiswa untuk mendapatkan learning goals</p><p>Struktur Portofolio :</p><ol><li>Halaman Judul</li><li>Kata Pengantar</li><li>Daftar Isi</li><li>Tujuan Pembelajaran</li><li>Perencanaan&nbsp;</li><li>Pelaksanaan (disertai bukti yang mendukung seperti resume kasus, hasil penilaian dan foto)</li><li>Refleksi (pencapaian tujuan belajar, kendala, manfaat)</li></ol><p>Rubrik Penilaian :</p><ul><li>Kelengkapan Format</li><li>Hubungan antara isi dan tujuan pembelajaran</li><li>Refleksi</li><li>Presentasi</li></ul><p><br></p><p><strong>Materi dr. Shofa Nur Fauzah, M.KM</strong></p><p>Kasus kasus yang membutuhkan peran keluarga yaitu pasien2 yang gagal pengobatan atau ada kesulitan dalam pengobatan pada level 3-5</p><p>Level 3 : Feelings and Support : Keluarga harus mendengarkan dan berempati terhadap papsien</p><p>Level 4 : Primary Care Family Assessment : Assess the relationship between he illness problem and the family dynamics</p><p>Level 5 :Medical Family Therapy : Intensive specialty care delivered by professional with advance training</p><p>5 Aspek Diagnosis Kedokteran Keluarga</p><ul><li><br></li></ul><ol><li>&nbsp;Aspek Personal. Keluhan utama, harapan dan kekhawatiran.</li><li>&nbsp;IAspek Klinis. Bila diagnosis klinis belum dapat ditegakkan cukup dengan diagnosis kerja dan diagnosis banding.</li><li>&nbsp;Aspek Internal. Kepribadian seseorang akan mempengaruhi perilaku. Karakteristik pribadi amat dipengaruhi oleh umur, jenis kelamin, pendidikan, pekerjaan, sosial ekonomi, kultur, etnis, dan lingkungan.</li><li>&nbsp;Aspek Eksternal. Psikososial, dan ekonomi keluarga</li><li>&nbsp;Skala Fungsi Sosial dan fungsional</li></ol><p><br></p><p><br></p><p>5 TOPIK WAWANCARA</p><p>YANG BERORIENTASI PADA KELUARGA</p><ol><li>Family History : Has anyone else in the family had this problem?</li><li>Health Beliefs : What do family member believe caused the problem and how should it be treated?</li><li>Concern : Who in the family is most concerned about the problem?</li><li>Family Stress and Change : Along with your illness, have there been any other recent changes or stresses in your life?</li><li>Support : How can your family or friends be helpful to you in dealing with the problem?</li></ol><p><br></p>',
            'tindaklanjut' => '<p><strong>Persamaan Persepsi DPK Stase Kompre</strong></p><p><br></p><p><strong>Evaluasi :&nbsp;</strong></p><ul><li>beberapa mahasiswa memiliki isi portofolio yang mirip/sama dengan temannya</li><li>Mahasiswa harus ditanyakan atau diingatkan atau diberikan trigger dulu</li><li>beberapa mahasiswa tidak sesuai dengan P1-P4 dalam penyusunan laporan</li></ul><p><br></p><p><strong>Materi dr. Vivi Meidianawaty M.Med.Ed</strong></p><p>&gt; Diharapkan dari refleksi diri ini didapatkan pelajaran untuk menyusun langkah yang lebih baik di masa depan..</p><p>&gt; Jika arahan dan bimbingan sesuai proses seharusnya tidak ada refleksi diri yang sama</p><p>&gt; Proses refleksi perlu dibantu masukan orang lain yang dianggap mampu memberikan umpan balik yang konstruktif</p><p><br></p><p>&gt; Proses Refleksi Diri :</p><ul><li>Apa yang terjadi... Kenapa terlambat mengumpulkan? Kenapa P1 dan P2nya tidak lengkap?</li><li>Bagaimana hal itu terjadi....Kendalanya dimana sehingga terlambat? Kendalanya dimana sehingga P1 dan P2 tidak lengkap ?</li><li>Pelajaran apa yang kamu ambil dari pengalaman ini.... dgn tujuan dpt mengcapture baik - atau +nya</li><li>Apa yang akan dilakukan untuk kedepannya.. nanti bagaimana kalau ada problem yang sama? apa yang dilakukan ?</li></ul><p>&gt;Tahapan Refleksi Diri :</p><ul><li>Tentukan 1 pengalaman berhaga</li><li>Analisis pengalaman dgn 4 pertanyaan diatas</li><li>Usahakan bukti eksternal (umpan balik dari berbagai pihak/log book)</li><li>Pembimbing sebagai teman sharing hasil refleksi&nbsp;</li></ul><p><br></p><p>&gt; Refleksi yang baik mencakup :</p><ul><li>Deskripsi pengalaman yang relevan dengan pemicu</li><li>Komponen refleksi (pelajaran yang didapat)</li><li>Bukti eksternal</li><li>Merujuk pada pengalaman sebelumnya&nbsp;</li><li>Action plan&nbsp;</li></ul><p><br></p><p><strong>Materi dr. Tissa Octavira, M.Med.Ed</strong></p><p>Memfasilitasi mahasiswa untuk mendapatkan learning goals</p><p>Struktur Portofolio :</p><ol><li>Halaman Judul</li><li>Kata Pengantar</li><li>Daftar Isi</li><li>Tujuan Pembelajaran</li><li>Perencanaan&nbsp;</li><li>Pelaksanaan (disertai bukti yang mendukung seperti resume kasus, hasil penilaian dan foto)</li><li>Refleksi (pencapaian tujuan belajar, kendala, manfaat)</li></ol><p>Rubrik Penilaian :</p><ul><li>Kelengkapan Format</li><li>Hubungan antara isi dan tujuan pembelajaran</li><li>Refleksi</li><li>Presentasi</li></ul><p><br></p><p><strong>Materi dr. Shofa Nur Fauzah, M.KM</strong></p><p>Kasus kasus yang membutuhkan peran keluarga yaitu pasien2 yang gagal pengobatan atau ada kesulitan dalam pengobatan pada level 3-5</p><p>Level 3 : Feelings and Support : Keluarga harus mendengarkan dan berempati terhadap papsien</p><p>Level 4 : Primary Care Family Assessment : Assess the relationship between he illness problem and the family dynamics</p><p>Level 5 :Medical Family Therapy : Intensive specialty care delivered by professional with advance training</p><p>5 Aspek Diagnosis Kedokteran Keluarga</p><ul><li><br></li></ul><ol><li>&nbsp;Aspek Personal. Keluhan utama, harapan dan kekhawatiran.</li><li>&nbsp;IAspek Klinis. Bila diagnosis klinis belum dapat ditegakkan cukup dengan diagnosis kerja dan diagnosis banding.</li><li>&nbsp;Aspek Internal. Kepribadian seseorang akan mempengaruhi perilaku. Karakteristik pribadi amat dipengaruhi oleh umur, jenis kelamin, pendidikan, pekerjaan, sosial ekonomi, kultur, etnis, dan lingkungan.</li><li>&nbsp;Aspek Eksternal. Psikososial, dan ekonomi keluarga</li><li>&nbsp;Skala Fungsi Sosial dan fungsional</li></ol><p><br></p><p><br></p><p>5 TOPIK WAWANCARA</p><p>YANG BERORIENTASI PADA KELUARGA</p><ol><li>Family History : Has anyone else in the family had this problem?</li><li>Health Beliefs : What do family member believe caused the problem and how should it be treated?</li><li>Concern : Who in the family is most concerned about the problem?</li><li>Family Stress and Change : Along with your illness, have there been any other recent changes or stresses in your life?</li><li>Support : How can your family or friends be helpful to you in dealing with the problem?</li></ol><p><br></p>',
