            'kesimpulan' => '<p>PBL KE 1 :</p><p>Trigger Kasus: <span style="color: red;">Diare akut dengan dehidrasi berat</span></p><p>Judul Skenario : BAB Cair</p><p>Note : Tambahan score dehidrasi untuk dewasa</p><p><br></p><p><br></p><p>PBL KE 2 : </p><p>Trigger Kasus : <span style="color: red;">Kecacingan</span></p><p>Judul Skenario : Nyeri Perut</p><p><br></p><p>PBL KE 3 : </p><p>Trigger Kasus: <span style="color: red;">Hematochezia ec colitis ulseratif&nbsp;</span></p><p>Judul Skenario : BAB Cair Bercampur Darah</p><p><br></p><p>PBL KE 4 : </p><p>Trigger Kasus:&nbsp;<span style="color: red;">Infeksi pada hepar&nbsp;(amebiasis hati/ bacterial, hepatitis virus)</span></p><p>Judul Skenario : Nyeri Perut Kanan Atas</p><p><br></p><p><br></p><p>PBL KE 5:</p><p>Trigger kasus: K<span style="color: red;">olangitis</span></p><p>Judul Skenario : Demam</p><p><br></p><p><br></p>',
