                'slug' => 'vIn6xlimAoglbYb0Jsk9',
            'kesimpulan' => '<p><strong>Skenario 1</strong></p><ul><li>Judul: BAK setelah minum kopi</li><li>Mindmap: -</li><li>Mininotes: anatomi, fisiologi</li></ul><p><br></p><p><strong>Skenario 2</strong></p><ul><li>Judul: oliguria</li><li>Skenario: dicantumkan nilai analisis gas darah (pH, PaCO2, dan HCO3)</li><li>Step 2: pertanyaan terkait pemeriksaan fisik dan pemeriksaan analisa gas darah dipisah</li><li>Mindmap: -</li><li>Mininotes: -</li></ul><p><br></p><p><strong>Skenario 3</strong></p><ul><li>Judul: tidak kunjung punya anak</li><li>Skenario: langsung dicantumkan hasilnya (oligospermia, teratozoospermia)</li><li>Mindmap: -</li><li>Mininotes: anatomi, biokimia, kelainan yang mungkin terjadi (pembentukan dan pengeluaran sperma)</li></ul><p><br></p><p><strong>Skenario 4</strong></p><ul><li>Judul: menstruasi tidak teratur </li><li>Skenario: detailkan pada skenario terkait periode menstruasi bulan ini dan dua bulan yang lalu  (perbedaan lamanya menstruasi)</li><li>Mindmap: -</li><li>Mininotes: -</li></ul><p><br></p><p><strong>Skenario 5</strong></p><ul><li>Judul: bertumbuh pendek</li><li>Skenario: ditambahkan tanda-tanda perubahan seksual perempuan</li><li>Mindmap: -</li><li>Mininotes: -</li></ul><p><br></p>',
