            'kesimpulan' => '<p><strong>EVALUASI</strong></p><p><strong>Koor Blok</strong></p><p><u>Semester 3 </u></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ada di blok 3.3</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ada 7 kuliah</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Sulit untuk mencari jadwal yang kosong dikarenakan jadwal penuh</p><p><u>Semester 7 </u></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ada di blok 7.1 </p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ada 1 kuliah</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Tidak ada kendala </p><p><strong>Departemen </strong></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Materi ajar: tetap dilanjutkan (karena sesuai dengan kurikulum sampai saat ini belum ada perubahan baik terkait materi dan pengampu)</p><p><br></p><p><strong>Review RPS</strong></p><p><u>Blok 3.3</u></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kuliah : masih relevan </p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Mata merah dengan penurunan visus&nbsp;: diubah menjadi belajar mandiri 1 x 50’ dan kuliah interaktif 1 x 50’ </p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PBL &gt; trigger: katarak senilis </p><p><u>Blok 7.1 </u></p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;CR : masih relevan</p><p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Trigger: trauma tembus mata </p>',
