                'slug' => '6JdwM8dV7NQZCyv0mXI4',
            'kesimpulan' => '<p class="ql-align-center"><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 1 </strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: SDH</p><p>-&nbsp;&nbsp;&nbsp;Keluhan demam di ganti menjadi kejang (pada diagram venn)</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: penurunan kesadaran</p><p>-&nbsp;&nbsp;&nbsp;RPS:</p><p>a.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Pasien tidak langsung mengalami penurunan kesadaran</p><p>b.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Masukan keluhan/gejala dari penyakit lain yang ada di diagram venn</p><p>-&nbsp;&nbsp;&nbsp;Pemeriksaan Fisik à status lokalis: dicari gambarannya</p><p>-&nbsp;&nbsp;&nbsp;Pemeriksaan penunjang à CT-Scan 1 lampiran hasil CT-Scan kepala saja (yang terpenting mahasiswa bisa mengetahui gambarannya)</p><p>&nbsp;</p><p><strong>Clinical Reasoning 2</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: retensio plasenta</p><p>-&nbsp;&nbsp;&nbsp;Diagram venn: perdarahan jalan lahir dan nyeri</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: keluar darah dari jalan lahir</p><p>-&nbsp;&nbsp;&nbsp;RPS: Masukan keluhan/gejala dari penyakit lain yang ada di diagram venn</p><p>-&nbsp;&nbsp;&nbsp;Pemeriksaan fisik: Masukan tanda-tanda dari penyakit lain yang ada di diagram venn</p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 3</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: DSS</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: Demam</p><p>-&nbsp;&nbsp;&nbsp;RPS: Masukan keluhan/gejala dari penyakit lain yang ada di diagram venn</p><p>-&nbsp;&nbsp;&nbsp;Pemeriksaan fisik: Masukan tanda-tanda dari penyakit lain yang ada di diagram venn</p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 4</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: Trauma tembus mata</p><p>-&nbsp;&nbsp;&nbsp;Diagram Venn: ditambahkan koagulum (karena di diagnosis ada)</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: nyeri pada mata kanan</p><p>-&nbsp;&nbsp;&nbsp;RPS: Masukan pekerjaan pasien (faktor risiko)</p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 5</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: Pemfigus Vulgaris &nbsp;</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: lepuh pada seluruh tubuh &nbsp;</p><p>-&nbsp;&nbsp;&nbsp;RPS: Masukan keluhan/gejala dari penyakit lain yang ada di diagram venn</p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 6</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: fraktur femur</p><p>-&nbsp;&nbsp;&nbsp;Diagram Venn: ditambahkan dislokasi sendi panggul</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: nyeri pada tungkai atas kiri</p><p>-&nbsp;&nbsp;&nbsp;Dikasih gambar terpisah untuk mahasiswa</p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 7</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: efusi pleura</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: sesak napas</p><p>-&nbsp;&nbsp;&nbsp;Tatalaksana: penatalaksanaan TB kasus baru</p><p><strong>&nbsp;</strong></p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 8</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: Appendisitis</p><p>-&nbsp;&nbsp;&nbsp;Diagram Venn: diisi list penyakit dengan keluhan nyeri perut kanan bawah (karena keluhan utamanya nyeri perut kanan bawah)</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: nyeri perut kanan bawah</p><p><strong>&nbsp;</strong></p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 9</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: KAD (ketoasidosis diabetikum)</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: tidak sadarkan diri</p><p><strong>&nbsp;</strong></p><p><strong>Clinical Reasoning 10</strong></p><p>-&nbsp;&nbsp;&nbsp;Kasus: CHF</p><p>-&nbsp;&nbsp;&nbsp;Diagram Venn: yang 1 keluhan di hapus (karena keluhan utama hanya sesak napas)</p><p>-&nbsp;&nbsp;&nbsp;Keluhan Utama: sesak napas</p><p>-&nbsp;&nbsp;&nbsp;Pemeriksaan penunjang : ditambahkan darah rutin, ureum, kreatinin, albumin</p>',
